include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <stdbool.h>

#define MAX_LENGHT 50

struct node {
    char data[MAX_LENGHT];
    struct node* next;
};

struct node* createNode(char* data) {
    struct node* newNode = (struct node*)malloc(sizeof(struct node));
    strcpy(newNode->data, data);
    newNode->next = NULL;
    return newNode;
}

void print(struct node* head) {
    struct node* temp = head;
    while (temp != NULL) {
        printf("%s -> ", temp->data);
        temp = temp->next;
    }
    printf("NULL\n");
}

int count(struct node* head) {
    int count = 0;
    struct node* temp = head;
    while (temp != NULL) {
        count++;
        temp = temp->next;
    }
    return count;
}

bool search(struct node* head, char* data) {
    struct node* temp = head;
    while (temp != NULL) {
        if (strcmp(temp->data, data) == 0) {
            return true;
        }
        temp = temp->next;
    }
    return false;
}

void insertAtBeginning(struct node** head, char* data) {
    struct node* newNode = createNode(data);
    newNode->next = *head;
    *head = newNode;
}

void insertAtEnd(struct node** head, char* data) {
    struct node* newNode = createNode(data);
    if (*head == NULL) {
        *head = newNode;
        return;
    }
    struct node* temp = *head;
    while (temp->next != NULL) {
        temp = temp->next;
    }
    temp->next = newNode;
}

void insertAfterNode(struct node* prevNode, char* data) {
    if (prevNode == NULL) {
        printf("The given previous node cannot be NULL\n");
        return;
    }
    struct node* newNode = createNode(data);
    newNode->next = prevNode->next;
    prevNode->next = newNode;
}

void deleteNode(struct node** head, char* data) {
    struct node* temp = *head;
    struct node* prev = NULL;
    if (temp != NULL && strcmp(temp->data, data) == 0) {
        *head = temp->next;
        free(temp);
        return;
    }
    while (temp != NULL && strcmp(temp->data, data) != 0) {
        prev = temp;
        temp = temp->next;
    }
    if (temp == NULL) {
        return;
    }
    prev->next = temp->next;
    free(temp);
}

void deleteList(struct node** head) {
    struct node* current = *head;
    struct node* next = NULL;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}

int main() {
    struct node* head = NULL;
    insertAtEnd(&head, "A");
    insertAtEnd(&head, "B");
    insertAtEnd(&head, "C");
    insertAtBeginning(&head, "D");
    insertAfterNode(head->next, "E");
    print(head);
    printf("Count: %d\n", count(head));
    printf("Search D: %s\n", search(head, "D") ? "Found" : "Not Found");
    printf("Search F: %s\n", search(head, "F") ? "Found" : "Not Found");
    deleteNode(&head, "E");
    print(head);
    deleteList(&head);
    print(head);
    return 0;
}
